		or snapshot.entryStaticTextY ~= (entry and entry.staticTextY)
		or snapshot.layoutStaticTextFont ~= (layout and layout.staticTextFont)
		or snapshot.layoutStaticTextSize ~= (layout and layout.staticTextSize)
